// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, address newOwner, address caller) public {
        // Ensure caller is different from initialOwner so the call comes from a non-owner
        vm.assume(initialOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(initialOwner != caller);
        vm.assume(initialOwner != newOwner);

        // Setup: set initial owner
        c.transferOwnership(initialOwner);

        // Record owner before the attempted transfer by a non-owner
        address ownerBefore = c.owner();

        // Non-owner calls transferOwnership
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // Assert: owner must remain unchanged (the reference modifier rejects the call; the buggy one allows it)
        assertTrue(c.owner() == ownerBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address ownerAddr, address nonOwnerAddr, address newOwner) public {
        vm.assume(ownerAddr != nonOwnerAddr);
        vm.assume(ownerAddr != address(0));
        vm.assume(nonOwnerAddr != address(0));
        vm.assume(newOwner != address(0));
        vm.prank(ownerAddr);
        c.transferOwnership(ownerAddr);
        address initialOwner = c.owner();
        vm.prank(nonOwnerAddr);
        (bool success,) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        assertTrue(!success && c.owner() == initialOwner);
    }
}

