pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address nonOwner) public {
        vm.assume(owner != nonOwner);
        c.transferOwnership(owner);
        vm.prank(nonOwner);
        bool ok;
        try c.transferOwnership(nonOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

